export const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function parseCoordinates(text){const m=text.trim().match(/^(-?\d+(?:\.\d+)?)\s*,\s*(-?\d+(?:\.\d+)?)$/);if(!m)return null;const lat=Number(m[1]),lon=Number(m[2]);return Math.abs(lat)<=90&&Math.abs(lon)<=180?{lat,lon}:null;}
export function distanceKm(a,b){const rad=x=>x*Math.PI/180;const dlat=rad(b.lat-a.lat),dlon=rad(b.lon-a.lon),h=Math.sin(dlat/2)**2+Math.cos(rad(a.lat))*Math.cos(rad(b.lat))*Math.sin(dlon/2)**2;return 6371*2*Math.atan2(Math.sqrt(h),Math.sqrt(Math.max(0,1-h)));}
export function normalizeResults(data){const seen=new Set();return (data.features||[]).flatMap(f=>{const p=f.properties||{},xy=f.geometry?.coordinates;const beach=p.osm_value==='beach';if(!beach&&p.osm_key!=='place')return [];if(!xy||!xy.every(Number.isFinite)||Math.abs(xy[0])>180||Math.abs(xy[1])>90)return [];const id=`${p.osm_type}-${p.osm_id}`;if(seen.has(id))return [];seen.add(id);return [{id,name:p.name||'Unnamed location',region:[p.city,p.state,p.country].filter((v,i,a)=>v&&a.indexOf(v)===i).join(', '),lat:xy[1],lon:xy[0],beach,kind:beach?'Beach':'Place · confirm shoreline'}]}).sort((a,b)=>Number(b.beach)-Number(a.beach));}
export function gridUsable(spot,marine){return Number.isFinite(marine?.latitude)&&Number.isFinite(marine?.longitude)&&distanceKm(spot,{lat:marine.latitude,lon:marine.longitude})<=35;}
